// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchmarkTask) predicate.BenchmarkTask {
	return predicate.BenchmarkTask(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchmarkTask) predicate.BenchmarkTask {
	return predicate.BenchmarkTask(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchmarkTask) predicate.BenchmarkTask {
	return predicate.BenchmarkTask(sql.NotPredicates(p))
}
